mapper.select:
SELECT user_id
FROM `user`
WHERE name = #{name} AND email = #{email}

SELECT COUNT(*) FROM `user` u
AND u.status = #{status}
AND (u.user_id LIKE CONCAT('%', #{keyword}, '%') OR u.name LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%'))

SELECT u.user_id, u.name, u.email, u.phone, u.status, u.is_locked, u.created_at, u.deleted_at FROM `user` u
AND u.status = #{status}
AND (u.user_id LIKE CONCAT('%', #{keyword}, '%') OR u.name LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY u.created_at DESC LIMIT #{offset}, #{size}
